#[allow(
    clippy::absurd_extreme_comparisons,
    clippy::len_zero,
    clippy::redundant_closure
)]
pub fn validate_event_payload(event: &str, payload: &Value) -> bool {
    match event {
        "projection.invalidated" => {
            serde_json::from_value::<ProjectionInvalidatedPayload>(payload.clone()).is_ok()
                && validate_projection_invalidated_payload(payload)
        }
        _ => false,
    }
}

